<!-- Organization settings: profile, subscription, billing and security. Simple forms with a save bar. -->
<template><template v-if="show.settings">
<div style="width: 100%; min-width: 0; display: flex; flex-direction: column; gap: 16px">
<div><h1 style="margin: 0; font-family: 'Space Grotesk', sans-serif; font-size: 28px; letter-spacing: -0.02em">Organization settings</h1>
<p style="margin: 4px 0 0; color: var(--k-9DB0A6,#9DB0A6)">Your organization's profile, plan, billing and security rules.</p></div>
<div role="tablist" style="display: flex; gap: 4px; border-bottom: 1px solid var(--k-24322C,#24322C); overflow-x: auto"><template v-for="(tb, tb__i) in settingsPage.tabs" :key="tb__i"><button role="tab" :aria-selected="tb.on" @click="tb.go" :style="`min-height: 44px; padding: 0 16px; border: 0; background: transparent; cursor: pointer; font-size: 14px; white-space: nowrap; font-family: inherit; border-bottom: 2px solid ${tb.on ? 'var(--k-B8F36B,#B8F36B)' : 'transparent'}; color: ${tb.on ? 'var(--k-E8EFEA,#E8EFEA)' : 'var(--k-9DB0A6,#9DB0A6)'}; font-weight: ${tb.on ? 600 : 500}`">{{ tb.label }}</button></template></div>

<!-- Profile -->
<template v-if="settingsPage.isProfile">
<div v-if="!settingsPage.profile.canEdit" role="status" style="padding: 10px 14px; border-radius: 12px; background: var(--k-2A2314,#2A2314); color: var(--k-FFD66B,#FFD66B); font-size: 13px">You can view this page. Ask an admin for the "Edit organization profile" right to change it.</div>
<div style="padding: 18px; border-radius: 16px; background: var(--k-16201C,#16201C); border: 1px solid var(--k-24322C,#24322C); display: flex; flex-wrap: wrap; align-items: center; gap: 14px">
<span :style="`width: 64px; height: 64px; flex: none; border-radius: 16px; overflow: hidden; background: #B8F36B; color: #0F1714; display: flex; align-items: center; justify-content: center; font-family: 'Space Grotesk', sans-serif; font-weight: 700; font-size: 22px`"><img v-if="settingsPage.profile.logo.url" :src="settingsPage.profile.logo.url" alt="Organization logo" style="width: 100%; height: 100%; object-fit: cover"><template v-else>{{ settingsPage.profile.logo.initials }}</template></span>
<div style="flex: 1 1 200px; min-width: 0; display: flex; flex-direction: column; gap: 2px"><strong style="font-size: 15px">Logo</strong><span style="font-size: 13px; color: var(--k-9DB0A6,#9DB0A6)">Shown in the top bar. Square images work best.</span></div>
<template v-if="settingsPage.profile.canEdit"><label style="position: relative; height: 38px; padding: 0 16px; border-radius: 19px; border: 1px solid var(--k-2A3832,#2A3832); display: flex; align-items: center; cursor: pointer; font-size: 14px"><input type="file" accept="image/*" aria-label="Upload logo" @change="settingsPage.profile.logo.onFile" style="position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; cursor: pointer">Upload logo</label>
<button v-if="settingsPage.profile.logo.url" @click="settingsPage.profile.logo.remove" style="height: 38px; padding: 0 16px; border-radius: 19px; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer; font-size: 14px">Remove</button></template>
</div>
<template v-for="(g, g__i) in settingsPage.profile.groups" :key="g__i">
<section :aria-label="g.title" style="padding: 18px; border-radius: 16px; background: var(--k-16201C,#16201C); border: 1px solid var(--k-24322C,#24322C); display: flex; flex-direction: column; gap: 12px"><strong style="font-size: 15px">{{ g.title }}</strong>
<div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); gap: 12px">
<template v-for="(fd, fd__i) in g.fields" :key="fd.key"><label :style="`display: flex; flex-direction: column; gap: 6px; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6); ${fd.wide ? 'grid-column: 1 / -1' : ''}`">{{ fd.label }}<template v-if="fd.required"> *</template>
<select v-if="fd.isSelect" :value="fd.value" :disabled="fd.disabled" @change="fd.onInput" style="height: 40px; padding: 0 10px; border-radius: 10px; border: 1px solid var(--k-2A3832,#2A3832); background: var(--k-121B17,#121B17); color: var(--k-E8EFEA,#E8EFEA); font-size: 14px"><template v-for="o in fd.options" :key="o"><option :value="o">{{ o }}</option></template></select>
<input v-else :type="fd.type" :value="fd.value" :placeholder="fd.placeholder" :disabled="fd.disabled" :aria-invalid="fd.hasErr" @input="fd.onInput" style="height: 40px; padding: 0 12px; border-radius: 10px; border: 1px solid var(--k-2A3832,#2A3832); background: var(--k-121B17,#121B17); color: var(--k-E8EFEA,#E8EFEA); font-size: 14px; min-width: 0">
<span v-if="fd.hasErr" role="alert" style="font-size: 12px; color: var(--k-FF9B8A,#FF9B8A)">{{ fd.err }}</span></label></template>
</div></section>
</template>
<div v-if="settingsPage.profile.canEdit" style="position: sticky; bottom: 0; z-index: 5; display: flex; flex-wrap: wrap; align-items: center; gap: 10px; padding: 12px 16px; border-radius: 14px; background: var(--k-1D2A25,#1D2A25); border: 1px solid var(--k-34453D,#34453D)">
<span :style="`flex: 1 1 140px; font-size: 13px; color: ${settingsPage.profile.dirty ? 'var(--k-FFB86B,#FFB86B)' : 'var(--k-9DB0A6,#9DB0A6)'}`">{{ settingsPage.profile.dirty ? 'You have unsaved changes' : 'All changes saved' }}</span>
<button :disabled="!settingsPage.profile.dirty" @click="settingsPage.profile.discard" style="height: 40px; padding: 0 18px; border-radius: 20px; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer">Discard</button>
<button :disabled="!settingsPage.profile.dirty" @click="settingsPage.profile.save" :style="`height: 40px; padding: 0 22px; border-radius: 20px; border: 0; font-weight: 600; cursor: ${settingsPage.profile.dirty ? 'pointer' : 'default'}; background: ${settingsPage.profile.dirty ? '#B8F36B' : 'var(--k-2A3832,#2A3832)'}; color: ${settingsPage.profile.dirty ? '#0F1714' : 'var(--k-9DB0A6,#9DB0A6)'}`">Save changes</button>
</div>
</template>

<!-- Subscription -->
<template v-if="settingsPage.isSub">
<div v-if="!settingsPage.canSub" role="status" style="padding: 10px 14px; border-radius: 12px; background: var(--k-2A2314,#2A2314); color: var(--k-FFD66B,#FFD66B); font-size: 13px">You can view the plan. Ask an admin for the "Manage subscription" right to change it.</div>
<section aria-label="Current plan" style="padding: 18px; border-radius: 16px; background: var(--k-16201C,#16201C); border: 1px solid var(--k-24322C,#24322C); display: flex; flex-direction: column; gap: 14px">
<div style="display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px"><div style="flex: 1 1 200px; min-width: 0"><span style="font-size: 12px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--k-9DB0A6,#9DB0A6)">Current plan</span><div style="font-family: 'Space Grotesk', sans-serif; font-size: 26px; font-weight: 700">{{ settingsPage.sub.planName }}</div><span style="font-size: 13px; color: var(--k-9DB0A6,#9DB0A6)">{{ settingsPage.sub.planBlurb }}</span></div>
<span :style="`padding: 4px 12px; border-radius: 14px; font-size: 12px; font-weight: 600; border: 1px solid ${settingsPage.sub.statusColor}; color: ${settingsPage.sub.statusColor}`">{{ settingsPage.sub.statusLabel }}</span></div>
<div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 180px), 1fr)); gap: 10px">
<div style="padding: 12px 14px; border-radius: 12px; background: var(--k-121B17,#121B17)"><span style="display: block; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6)">Monthly total</span><strong style="font-size: 18px">{{ settingsPage.sub.total }}</strong><span style="display: block; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6)">{{ settingsPage.sub.totalNote }}</span></div>
<div style="padding: 12px 14px; border-radius: 12px; background: var(--k-121B17,#121B17)"><span style="display: block; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6)">{{ settingsPage.sub.cycleLabel }}</span><strong style="font-size: 18px">Renews {{ settingsPage.sub.renews }}</strong><span style="display: block; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6)">{{ settingsPage.sub.autoRenew ? 'Auto-renew is on' : 'Auto-renew is off' }}</span></div>
<div style="padding: 12px 14px; border-radius: 12px; background: var(--k-121B17,#121B17)"><span style="display: block; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6)">Seats</span><strong style="font-size: 18px">{{ settingsPage.sub.seats }} <span style="font-size: 12px; font-weight: 500; color: var(--k-9DB0A6,#9DB0A6)">of {{ settingsPage.sub.seatLimit }} on this plan</span></strong>
<div style="height: 6px; border-radius: 3px; background: var(--k-2A3832,#2A3832); margin: 6px 0 4px; overflow: hidden"><div :style="`height: 100%; width: ${settingsPage.sub.seatPct}%; background: ${settingsPage.sub.seatWarn ? '#FF9B8A' : '#B8F36B'}`"></div></div>
<span :style="`font-size: 12px; color: ${settingsPage.sub.seatWarn ? 'var(--k-FF9B8A,#FF9B8A)' : 'var(--k-9DB0A6,#9DB0A6)'}`">{{ settingsPage.sub.seatNote }}</span></div>
</div>
<div v-if="settingsPage.canSub" style="display: flex; flex-wrap: wrap; align-items: center; gap: 10px">
<span style="font-size: 13px; color: var(--k-C9D6CF,#C9D6CF)">Seats</span>
<button aria-label="Remove 10 seats" @click="settingsPage.sub.setSeats(-10)" style="width: 38px; height: 38px; border-radius: 50%; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer; font-size: 16px">−</button>
<strong style="min-width: 44px; text-align: center">{{ settingsPage.sub.seats }}</strong>
<button aria-label="Add 10 seats" @click="settingsPage.sub.setSeats(10)" style="width: 38px; height: 38px; border-radius: 50%; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer; font-size: 16px">+</button>
<span style="font-size: 12px; color: var(--k-9DB0A6,#9DB0A6)">in steps of 10</span>
<span style="flex: 1"></span>
<button @click="settingsPage.sub.toggleCycle" style="height: 38px; padding: 0 16px; border-radius: 19px; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer; font-size: 13px">{{ settingsPage.sub.cycle === 'annual' ? 'Switch to monthly billing' : 'Switch to yearly billing (save 20%)' }}</button>
<button role="switch" :aria-checked="settingsPage.sub.autoRenew" @click="settingsPage.sub.toggleAuto" style="height: 38px; padding: 0 16px; border-radius: 19px; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer; font-size: 13px">Auto-renew: {{ settingsPage.sub.autoRenew ? 'On' : 'Off' }}</button>
</div>
</section>
<section aria-label="Plans" style="display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 230px), 1fr)); gap: 12px">
<template v-for="pl in settingsPage.sub.plans" :key="pl.id"><div :style="`padding: 16px; border-radius: 16px; background: var(--k-16201C,#16201C); border: 1px solid ${pl.current ? 'var(--k-B8F36B,#B8F36B)' : 'var(--k-24322C,#24322C)'}; display: flex; flex-direction: column; gap: 8px`">
<div style="display: flex; align-items: center; gap: 8px"><strong style="font-size: 16px; flex: 1">{{ pl.name }}</strong><span v-if="pl.current" style="font-size: 11px; font-weight: 700; color: var(--k-B8F36B,#B8F36B)">CURRENT</span></div>
<span style="font-size: 13px; color: var(--k-9DB0A6,#9DB0A6)">{{ pl.blurb }}</span><strong style="font-size: 14px">{{ pl.price }}</strong>
<ul style="margin: 0; padding-left: 18px; font-size: 13px; color: var(--k-C9D6CF,#C9D6CF); display: flex; flex-direction: column; gap: 2px"><template v-for="f in pl.features" :key="f"><li>{{ f }}</li></template></ul>
<button v-if="pl.canChoose" @click="pl.choose" style="margin-top: auto; height: 38px; border-radius: 19px; border: 0; background: #B8F36B; color: #0F1714; font-weight: 600; cursor: pointer">{{ pl.action }}</button></div></template>
</section>
<section aria-label="Add-ons" style="padding: 18px; border-radius: 16px; background: var(--k-16201C,#16201C); border: 1px solid var(--k-24322C,#24322C); display: flex; flex-direction: column; gap: 10px"><strong style="font-size: 15px">Add-ons</strong>
<template v-for="ad in settingsPage.sub.addons" :key="ad.id"><div style="display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; padding: 10px 12px; border-radius: 12px; background: var(--k-121B17,#121B17)"><div style="flex: 1 1 200px; min-width: 0"><strong style="font-size: 14px">{{ ad.name }}</strong><span style="display: block; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6)">{{ ad.desc }} · {{ ad.priceLabel }}</span></div>
<button role="switch" :aria-checked="ad.on" :disabled="!settingsPage.canSub" @click="ad.toggle" :style="`height: 34px; padding: 0 16px; border-radius: 17px; cursor: pointer; font-size: 13px; font-weight: 600; ${ad.on ? 'border: 1px solid var(--k-B8F36B,#B8F36B); background: var(--k-2C3D34,#2C3D34); color: var(--k-E8EFEA,#E8EFEA)' : 'border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA)'}`">{{ ad.on ? 'Added' : 'Add' }}</button></div></template>
</section>
<section v-if="settingsPage.canSub" aria-label="Cancel subscription" style="padding: 18px; border-radius: 16px; background: var(--k-16201C,#16201C); border: 1px solid var(--k-4A2A2A,#4A2A2A); display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px"><div style="flex: 1 1 240px; min-width: 0"><strong style="font-size: 15px">{{ settingsPage.sub.cancelling ? 'Cancellation scheduled' : 'Cancel subscription' }}</strong><span style="display: block; font-size: 13px; color: var(--k-9DB0A6,#9DB0A6)">{{ settingsPage.sub.cancelling ? settingsPage.sub.statusLabel + '. You can resume any time before then.' : 'Everyone keeps access until the end of the paid period.' }}</span></div>
<button v-if="settingsPage.sub.cancelling" @click="settingsPage.sub.resume" style="height: 40px; padding: 0 20px; border-radius: 20px; border: 0; background: #B8F36B; color: #0F1714; font-weight: 600; cursor: pointer">Resume subscription</button>
<button v-else @click="settingsPage.sub.cancel" style="height: 40px; padding: 0 20px; border-radius: 20px; border: 1px solid var(--k-FF9B8A,#FF9B8A); background: transparent; color: var(--k-FF9B8A,#FF9B8A); font-weight: 600; cursor: pointer">Cancel subscription</button></section>
</template>

<!-- Billing -->
<template v-if="settingsPage.isBilling">
<section aria-label="Payment method" style="padding: 18px; border-radius: 16px; background: var(--k-16201C,#16201C); border: 1px solid var(--k-24322C,#24322C); display: flex; flex-direction: column; gap: 12px"><strong style="font-size: 15px">Payment method</strong>
<div style="display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px"><div style="flex: 1 1 200px; min-width: 0"><strong style="font-size: 16px">{{ settingsPage.billing.cardLabel }}</strong><span style="display: block; font-size: 13px; color: var(--k-9DB0A6,#9DB0A6)">{{ settingsPage.billing.cardExp }}</span></div>
<button v-if="settingsPage.canSub" @click="settingsPage.billing.toggleCard" :aria-expanded="settingsPage.billing.cardOpen" style="height: 38px; padding: 0 18px; border-radius: 19px; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer; font-size: 14px">{{ settingsPage.billing.cardOpen ? 'Cancel' : 'Update card' }}</button></div>
<form v-if="settingsPage.billing.cardOpen" novalidate @submit.prevent="settingsPage.billing.card.save" style="display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 200px), 1fr)); gap: 10px; align-items: end">
<label style="display: flex; flex-direction: column; gap: 6px; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6); grid-column: span 2">Card number<input type="text" inputmode="numeric" autocomplete="off" :value="settingsPage.billing.card.number" @input="settingsPage.billing.card.onNumber" placeholder="4242 4242 4242 4242" style="height: 40px; padding: 0 12px; border-radius: 10px; border: 1px solid var(--k-2A3832,#2A3832); background: var(--k-121B17,#121B17); color: var(--k-E8EFEA,#E8EFEA); font-size: 14px"></label>
<label style="display: flex; flex-direction: column; gap: 6px; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6)">Expiry<input type="text" :value="settingsPage.billing.card.exp" @input="settingsPage.billing.card.onExp" placeholder="MM/YY" style="height: 40px; padding: 0 12px; border-radius: 10px; border: 1px solid var(--k-2A3832,#2A3832); background: var(--k-121B17,#121B17); color: var(--k-E8EFEA,#E8EFEA); font-size: 14px"></label>
<button type="submit" style="height: 40px; border-radius: 20px; border: 0; background: #B8F36B; color: #0F1714; font-weight: 600; cursor: pointer">Save card</button>
<span v-if="settingsPage.billing.card.hasErr" role="alert" style="grid-column: 1 / -1; font-size: 13px; color: var(--k-FF9B8A,#FF9B8A)">{{ settingsPage.billing.card.err }}</span></form>
</section>
<section aria-label="Billing contact" style="padding: 18px; border-radius: 16px; background: var(--k-16201C,#16201C); border: 1px solid var(--k-24322C,#24322C); display: flex; flex-direction: column; gap: 12px"><strong style="font-size: 15px">Billing contact</strong>
<div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); gap: 12px">
<template v-for="fd in settingsPage.billing.contact" :key="fd.key"><label :style="`display: flex; flex-direction: column; gap: 6px; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6); ${fd.wide ? 'grid-column: 1 / -1' : ''}`">{{ fd.label }}<input :type="fd.type" :value="fd.value" :disabled="!settingsPage.canSub" :aria-invalid="fd.hasErr" @input="fd.onInput" style="height: 40px; padding: 0 12px; border-radius: 10px; border: 1px solid var(--k-2A3832,#2A3832); background: var(--k-121B17,#121B17); color: var(--k-E8EFEA,#E8EFEA); font-size: 14px; min-width: 0"><span v-if="fd.hasErr" role="alert" style="font-size: 12px; color: var(--k-FF9B8A,#FF9B8A)">{{ fd.err }}</span></label></template></div>
<div v-if="settingsPage.canSub" style="display: flex; flex-wrap: wrap; gap: 10px; align-items: center"><span :style="`flex: 1 1 120px; font-size: 13px; color: ${settingsPage.billing.dirty ? 'var(--k-FFB86B,#FFB86B)' : 'var(--k-9DB0A6,#9DB0A6)'}`">{{ settingsPage.billing.dirty ? 'Unsaved changes' : 'All saved' }}</span>
<button :disabled="!settingsPage.billing.dirty" @click="settingsPage.billing.discard" style="height: 38px; padding: 0 16px; border-radius: 19px; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer">Discard</button>
<button :disabled="!settingsPage.billing.dirty" @click="settingsPage.billing.save" :style="`height: 38px; padding: 0 20px; border-radius: 19px; border: 0; font-weight: 600; cursor: ${settingsPage.billing.dirty ? 'pointer' : 'default'}; background: ${settingsPage.billing.dirty ? '#B8F36B' : 'var(--k-2A3832,#2A3832)'}; color: ${settingsPage.billing.dirty ? '#0F1714' : 'var(--k-9DB0A6,#9DB0A6)'}`">Save changes</button></div>
</section>
<section aria-label="Invoices" style="padding: 18px; border-radius: 16px; background: var(--k-16201C,#16201C); border: 1px solid var(--k-24322C,#24322C); display: flex; flex-direction: column; gap: 10px"><div style="display: flex; flex-wrap: wrap; align-items: center; gap: 10px"><strong style="font-size: 15px; flex: 1">Invoices</strong><button @click="settingsPage.billing.downloadAll" style="height: 36px; padding: 0 16px; border-radius: 18px; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer; font-size: 13px">Download all (Excel)</button></div>
<template v-for="iv in settingsPage.billing.invoices" :key="iv.no"><div style="display: flex; flex-wrap: wrap; align-items: center; gap: 6px 14px; padding: 10px 12px; border-radius: 12px; background: var(--k-121B17,#121B17)"><span style="font-family: ui-monospace, monospace; font-size: 13px; flex: 1 1 130px">{{ iv.no }}</span><span style="font-size: 13px; color: var(--k-9DB0A6,#9DB0A6); flex: 1 1 100px">{{ iv.dateLabel }}</span><strong style="font-size: 14px; flex: 1 1 110px">{{ iv.amountLabel }}</strong><span :style="`font-size: 12px; font-weight: 600; color: ${iv.color}`">{{ iv.status }}</span><button @click="iv.openInvoice" :aria-label="`Print tax invoice ${iv.no}`" style="height: 32px; padding: 0 14px; border-radius: 16px; border: 0; background: #B8F36B; color: #0F1714; font-weight: 600; cursor: pointer; font-size: 12px">Tax invoice</button><button v-if="iv.isPaid" @click="iv.openReceipt" :aria-label="`Print receipt ${iv.no}`" style="height: 32px; padding: 0 14px; border-radius: 16px; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer; font-size: 12px">Receipt</button><button @click="iv.download" :aria-label="`Download ${iv.no}`" style="height: 32px; padding: 0 12px; border-radius: 16px; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer; font-size: 12px">Excel</button></div></template></section>
</template>

<!-- Security & data -->
<template v-if="settingsPage.isSecurity">
<div v-if="!settingsPage.security.canEdit" role="status" style="padding: 10px 14px; border-radius: 12px; background: var(--k-2A2314,#2A2314); color: var(--k-FFD66B,#FFD66B); font-size: 13px">You can view these settings. Ask an admin for the "Edit organization profile" right to change them.</div>
<section aria-label="Security" style="padding: 18px; border-radius: 16px; background: var(--k-16201C,#16201C); border: 1px solid var(--k-24322C,#24322C); display: flex; flex-direction: column; gap: 12px"><strong style="font-size: 15px">Sign-in and sharing</strong>
<template v-for="fl in settingsPage.security.flags" :key="fl.key"><div style="display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; padding: 10px 12px; border-radius: 12px; background: var(--k-121B17,#121B17)"><div style="flex: 1 1 220px; min-width: 0"><strong style="font-size: 14px">{{ fl.label }}</strong><span style="display: block; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6)">{{ fl.note }}</span></div><button role="switch" :aria-checked="fl.on" :disabled="fl.disabled" @click="fl.toggle" :style="`height: 34px; padding: 0 18px; border-radius: 17px; cursor: pointer; font-size: 13px; font-weight: 600; ${fl.on ? 'border: 1px solid var(--k-B8F36B,#B8F36B); background: var(--k-2C3D34,#2C3D34); color: var(--k-E8EFEA,#E8EFEA)' : 'border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA)'}`">{{ fl.on ? 'On' : 'Off' }}</button></div></template>
<div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); gap: 12px">
<template v-for="fd in settingsPage.security.fields" :key="fd.key"><label :style="`display: flex; flex-direction: column; gap: 6px; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6); ${fd.wide ? 'grid-column: 1 / -1' : ''}`">{{ fd.label }}<span v-if="fd.isSelect" style="display: flex; align-items: center; gap: 8px"><select :value="fd.value" :disabled="fd.disabled" @change="fd.onInput" style="flex: 1; height: 40px; padding: 0 10px; border-radius: 10px; border: 1px solid var(--k-2A3832,#2A3832); background: var(--k-121B17,#121B17); color: var(--k-E8EFEA,#E8EFEA); font-size: 14px"><template v-for="o in fd.options" :key="o"><option :value="o">{{ fd.optLabel(o) }}</option></template></select></span>
<input v-else :type="fd.type" :value="fd.value" :placeholder="fd.placeholder" :disabled="fd.disabled" @input="fd.onInput" style="height: 40px; padding: 0 12px; border-radius: 10px; border: 1px solid var(--k-2A3832,#2A3832); background: var(--k-121B17,#121B17); color: var(--k-E8EFEA,#E8EFEA); font-size: 14px; min-width: 0"></label></template></div>
<div v-if="settingsPage.security.canEdit" style="display: flex; flex-wrap: wrap; gap: 10px; align-items: center"><span :style="`flex: 1 1 120px; font-size: 13px; color: ${settingsPage.security.dirty ? 'var(--k-FFB86B,#FFB86B)' : 'var(--k-9DB0A6,#9DB0A6)'}`">{{ settingsPage.security.dirty ? 'Unsaved changes' : 'All saved' }}</span>
<button :disabled="!settingsPage.security.dirty" @click="settingsPage.security.discard" style="height: 38px; padding: 0 16px; border-radius: 19px; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer">Discard</button>
<button :disabled="!settingsPage.security.dirty" @click="settingsPage.security.save" :style="`height: 38px; padding: 0 20px; border-radius: 19px; border: 0; font-weight: 600; cursor: ${settingsPage.security.dirty ? 'pointer' : 'default'}; background: ${settingsPage.security.dirty ? '#B8F36B' : 'var(--k-2A3832,#2A3832)'}; color: ${settingsPage.security.dirty ? '#0F1714' : 'var(--k-9DB0A6,#9DB0A6)'}`">Save changes</button></div>
<StorageLimits v-if="settingsPage.security.canEdit" />
</section>
<section aria-label="Your data" style="padding: 18px; border-radius: 16px; background: var(--k-16201C,#16201C); border: 1px solid var(--k-24322C,#24322C); display: flex; flex-direction: column; gap: 12px"><strong style="font-size: 15px">Your data</strong>
<div style="display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px"><div style="flex: 1 1 240px; min-width: 0"><strong style="font-size: 14px">Export organization data</strong><span style="display: block; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6)">Profile, people and subscription as a JSON file.</span></div><button @click="settingsPage.security.exportData" style="height: 38px; padding: 0 18px; border-radius: 19px; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer">Export data</button></div>
<div v-if="settingsPage.canSub" style="display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; padding-top: 12px; border-top: 1px solid var(--k-24322C,#24322C)"><div style="flex: 1 1 240px; min-width: 0"><strong style="font-size: 14px; color: var(--k-FF9B8A,#FF9B8A)">Delete organization</strong><span style="display: block; font-size: 12px; color: var(--k-9DB0A6,#9DB0A6)">Removes the organization and all its data after an admin confirms.</span></div><button @click="settingsPage.security.del" style="height: 38px; padding: 0 18px; border-radius: 19px; border: 1px solid var(--k-FF9B8A,#FF9B8A); background: transparent; color: var(--k-FF9B8A,#FF9B8A); cursor: pointer">Request deletion</button></div>
</section>
</template>

<section v-if="settingsPage.isSecurity" aria-label="Legal documents" style="padding: 18px; border-radius: 16px; background: var(--k-16201C,#16201C); border: 1px solid var(--k-24322C,#24322C); display: flex; flex-direction: column; gap: 10px"><strong style="font-size: 15px">Legal documents</strong>
<div style="display: flex; flex-wrap: wrap; gap: 8px"><template v-for="d in legalDocs" :key="d.slug"><NuxtLink :to="d.path" target="_blank" :title="d.summary" style="height: 36px; padding: 0 16px; border-radius: 18px; border: 1px solid var(--k-2A3832,#2A3832); color: var(--k-E8EFEA,#E8EFEA); font-size: 13px; display: flex; align-items: center; text-decoration: none">{{ d.title }}</NuxtLink></template></div></section>

<!-- Confirm -->
<template v-if="settingsPage.confirm.open">
<div class="hub-overlay" style="position: fixed; inset: 0; z-index: 70; background: rgba(5,10,8,0.6); display: flex; align-items: center; justify-content: center; padding: 16px">
<div role="alertdialog" aria-modal="true" aria-label="Confirm" style="width: 440px; max-width: 100%; padding: 20px; border-radius: 20px; background: var(--k-16201C,#16201C); border: 1px solid var(--k-2A3832,#2A3832); display: flex; flex-direction: column; gap: 14px">
<p style="margin: 0; font-size: 15px; line-height: 1.5">{{ settingsPage.confirm.text }}</p>
<input v-if="settingsPage.confirm.needsName" type="text" :value="settingsPage.confirm.typed" @input="settingsPage.confirm.onTyped" :placeholder="settingsPage.orgName" aria-label="Type the organization name" style="height: 40px; padding: 0 12px; border-radius: 10px; border: 1px solid var(--k-2A3832,#2A3832); background: var(--k-121B17,#121B17); color: var(--k-E8EFEA,#E8EFEA); font-size: 14px">
<div style="display: flex; gap: 8px; justify-content: flex-end"><button @click="settingsPage.confirm.cancel" style="height: 40px; padding: 0 18px; border-radius: 20px; border: 1px solid var(--k-2A3832,#2A3832); background: transparent; color: var(--k-E8EFEA,#E8EFEA); cursor: pointer">Not now</button><button :disabled="!settingsPage.confirm.ready" @click="settingsPage.confirm.run" :style="`height: 40px; padding: 0 22px; border-radius: 20px; border: 0; font-weight: 600; cursor: ${settingsPage.confirm.ready ? 'pointer' : 'default'}; background: ${settingsPage.confirm.ready ? '#B8F36B' : 'var(--k-2A3832,#2A3832)'}; color: ${settingsPage.confirm.ready ? '#0F1714' : 'var(--k-9DB0A6,#9DB0A6)'}`">{{ settingsPage.confirm.label }}</button></div>
</div></div>
</template>
</div>
</template></template>

<script>
import { hubBindings } from '~/composables/useHub';
import { LEGAL_DOCS } from '~/logic/legal.js';

export default {
  name: 'SettingsSection',
  data() { return { legalDocs: LEGAL_DOCS }; },
  ...hubBindings(["settingsPage","show"])
};
</script>
